// Turns the JSON schema of a registry setting (generated by pydantic) into the kind of editor the UI renders.

export type Editor =
  | { kind: "boolean"; nullable: boolean }
  | { kind: "integer"; nullable: boolean; min?: number; max?: number }
  | { kind: "number"; nullable: boolean; min?: number; max?: number }
  | { kind: "enum"; nullable: boolean; options: string[] }
  | { kind: "list"; nullable: boolean }
  | { kind: "string"; nullable: boolean; format?: string };

type Schema = Record<string, unknown>;

function variants(schema: Schema): { main: Schema; nullable: boolean } {
  const anyOf = schema.anyOf as Schema[] | undefined;
  if (!anyOf) return { main: schema, nullable: false };
  const nonNull = anyOf.filter((option) => option.type !== "null");
  return { main: nonNull[0] ?? {}, nullable: nonNull.length < anyOf.length };
}

export function editorFor(schema: Schema): Editor {
  const { main, nullable } = variants(schema);
  if (Array.isArray(main.enum)) return { kind: "enum", nullable, options: main.enum.map(String) };
  if (main.const !== undefined) return { kind: "enum", nullable, options: [String(main.const)] };
  switch (main.type) {
    case "boolean":
      return { kind: "boolean", nullable };
    case "integer":
      return {
        kind: "integer",
        nullable,
        min: typeof main.minimum === "number" ? main.minimum : undefined,
        max: typeof main.maximum === "number" ? main.maximum : undefined,
      };
    case "number":
      return {
        kind: "number",
        nullable,
        min: typeof main.minimum === "number" ? main.minimum : undefined,
        max: typeof main.maximum === "number" ? main.maximum : undefined,
      };
    case "array":
      return { kind: "list", nullable };
    default:
      return { kind: "string", nullable, format: typeof main.format === "string" ? main.format : undefined };
  }
}

/** Text shown in an input for a stored value. */
export function toInput(editor: Editor, value: unknown): string {
  if (value === null || value === undefined) return "";
  if (editor.kind === "list") return (value as unknown[]).map(String).join("\n");
  return String(value);
}

/** Value sent to the API from the input text. Empty means null for nullable settings. */
export function fromInput(editor: Editor, text: string): unknown {
  const trimmed = text.trim();
  if (editor.kind === "list") {
    return trimmed
      .split(/[\n,]/)
      .map((item) => item.trim())
      .filter(Boolean);
  }
  if (trimmed === "" && editor.nullable) return null;
  if (editor.kind === "integer" || editor.kind === "number") return Number(trimmed);
  return trimmed;
}
